\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f3\lang1033\fs24 162\plain \f3\super\lang1033\fs24 v\plain \f3\lang1033\fs24 \endash 166\plain \f3\super\lang1033\fs24 v\plain \f3\lang1033\fs24  \plain \f3\scaps\lang1033\fs24 Wiedereinverleibung von Preussen. \plain \f3\lang1033\fs24 Durch das K\u246 \'f6nigreich Polen\plain \f3\i\lang1033\fs24 . Im Namen des Herren. Amen. Zu dieser Sache ewigen Ged\u228 \'e4chtn\u252 \'fcss. Weil die g\u246 \'f6ttlichen und menschlichen Berater auch die he\u255 \'fflsamen Constitutiones, Ordnung und Decreta ... \endash  ... Geschehen und gegeben in der Stadt Thoren am nachsten Montage nach dem Sontage Palmarum im Jahr des Herren 1454 \plain \f3\lang1033\fs24 [Thorn, 1454 IV 15]. Lateinischer Druck: Codex Diplomaticus Regni Poloni\u230 \'e6 et Magni Ducatus Lituani\u230 \'e6,\plain \f0\b\fs24  \plain \f3\lang1033\fs24 Bd. 4, bearb. von Mathias Dogiel, K\u246 \'f6nigsberg, Leipzig, Wilna 1764, S. 149\endash 152, Nr. CVIII; dazu Regest in: Acten der St\u228 \'e4ndetage Preu\u223 \'dfens unter der Herrschaft des Deutschen Ordens, Bd. 4, hg. von Max T\u246 \'f6ppen, Leipzig 1884, S. 403, Nr. 262.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset1 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman;}{\f3\fnil\fcharset0 Arial;}{\f4\fnil\fcharset204 Arial;}{\f5\fnil\fcharset238 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f3\lang1033\fs24 166\plain \f3\super\lang1033\fs24 v\plain \f3\lang1033\fs24 \endash 168\plain \f3\super\lang1033\fs24 r\plain \f3\lang1033\fs24  \plain \f3\scaps\lang1033\fs24 Eid der Stadt Danzig. \plain \f3\lang1033\fs24 Gegen\u252 \'fcber der Krone Polen. \plain \f3\i\lang1033\fs24 Hierauff folget der sonderliche E\u255 \'ffdt, welchen die Stadt Dantzigk bald darnach der hochgemelten k\u246 \'f6niglichen Ma\u255 \'ffest\u228 \'e4t undt der Krone Pohlen gethan hat ... \endash  ... Welcher E\u255 \'ffdt dann in den k\u246 \'f6niglichen Statuten g\u228 \'e4ntzlich und vollenkomlich auss gedrucket worden ist. Dass gantze Landt Preussen nach Culmisch Recht, auss genommen die 3 St\u228 \'e4tte Elbing, Frauenburg undt Braunsberg, die haben L\u252 \'fcbisch Recht \plain \f3\lang1033\fs24 [1454]. Lateinischer Druck: Codex Diplomaticus Regni Poloni\u230 \'e6 Et Magni Ducatus Lituani\u230 \'e6,\plain \f0\b\fs24  \plain \f3\lang1033\fs24 Bd. 4, bearb. von Mathias Dogiel, K\u246 \'f6nigsberg, Leipzig, Wilna 1764, S. 154 f., Nr. CXII; dazu Regest in: Acten der St\u228 \'e4ndetage Preu\u223 \'dfens unter der Herrschaft des Deutschen Ordens, Bd. 4, hg. von Max T\u246 \'f6ppen, Leipzig 1884, S. 429, Nr. 283.}

