\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 1\plain \f0\super\fs32 r\plain \f0\fs24 -16\plain \f0\super\fs32 v\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Kurze Geschichte Italiens}}\plain \f0\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Come Attila flagellum Dei nacque et a che modo venne al mondo}}\plain \f0\i\fs24 .\plain \f0\scaps\fs24  \plain \f0\i\fs24 Da poi la passion del nostro signor Jesus Cristo, li soi apostolli furno dispersi ... - ... Da poi Rigo quarto \plain \f0\fs24 [!] [Heinrich IV., \u8224 \'86 1106, statt sein Sohn Heinrich V., \u8224 \'86 1125]\plain \f0\i\fs24  se pacifico con Santa Gesia \plain \f0\fs24 [1123]\plain \f0\i\fs24  e mori del 1125. Da poi Rigo quarto \plain \f0\fs24 [!] \plain \f0\i\fs24 succedette nel imperio Luterio de Sansogna \plain \f0\fs24 [Lothar III. von S\u252 \'fcpplingenburg, 1125-1137, Kaiser 1133]\plain \f0\i\fs24  et \plain \f0\fs24 [!] \plain \f0\i\fs24 in lui fini la casa de Baviera lo imperio, che quatro Henrigi avena tenuto lo imperio l'un dredo l'altro.}

