\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 33\plain \f0\super\fs32 v\plain \f0\fs24 -37\plain \f0\super\fs32 v\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Verecundia in confessione}}\plain \f0\scaps\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Iugo laborat mens pariendo}}\plain \f0\i\fs24  ... - ... quod de dicto sunt scripta. \plain \f0\fs24 Weder mit Meier, Jakob von J\u252 \'fcterbog, 1955, S. 20, Nr. 12 noch mit ebd., S. 60 f., Nr. 73 identisch; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Mertens, Iacobus Carthusiensis, 1976}}\plain \f0\fs24 , S. 277, 283.}

