\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 181\plain \f0\super\fs32 r\plain \f0\fs24 -183\plain \f0\super\fs32 v\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Gertrudis de Helfta}}\plain \f0\scaps\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Legatus divinae pietatis}}\plain \f0\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Ipsa beata Truta per id verbum: Abel, ubi est frater tuus? intellexit, qui dominus a quolibet religioso requiret}}\plain \f0\i\fs24  ... - ... neglexerit indebita devocione et attencione. \plain \f0\fs24 Ed.: Sanct\u230 \'e6 Gertrudis magn\u230 \'e6, Legatus divin\u230 \'e6 pietatis III 76-81 (Revelationes Gertrudian\u230 \'e6 ac Mechtildian\u230 \'e6 1), Poitiers, Paris 1875, S. 264-275.}

