INK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\fs24\chcbpat17  [1446 VII 25] }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 protunc existente domino rege Kazymiro}}\plain \f0\fs24\chcbpat17  \plain \f0\fs24 [Kasimir IV. Jagiello, K\u246 \'f6nig von Polen, 1447-1492] {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 necnon et reverendissimo domino Iohanne Cruscz\u255 \'ffnsk\u255 \'ff archiepiscopo et primate infra Prussie alteris }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 [}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 Johann III. Gruszczynski, erst }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 1464-1473 Erzbischof von Gnesen] }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 in Marbork}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\fs24\chcbpat17  [Marienburg] }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 cum milicia regni et aliis stipendariis. Domine Ihesu Christe, fac faciem bonum, ut cum salute (...) bono, sed pro tempore in Marbork}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 finxerat se ire et in Bidgocze}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\fs24\chcbpat17  [Bromberg] (...)}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17  sunt metati expectantes, ut viderunt tacti in obsidione Cho\u255 \'ffnycze}}\plain \f0\i\fs24  \plain \f0\fs24 [Konitz], Lateinisches Kolophon. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Colophons}}\plain \f0\fs24