\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24\cf1 2\plain \f2\super\lang1033\fs32\cf1 ra\plain \f2\lang1033\fs24\cf1 -42\plain \f2\super\lang1033\fs32\cf1 va \plain \f2\scaps\lang1033\fs24\cf1 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs24\chcbpat17\cf1 Gualterus Burlaeus}}\plain \f2\scaps\lang1033\fs24\cf1 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs24\chcbpat17\cf1 Liber}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs24\chcbpat17  de }}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs24\chcbpat17\cf1 vita}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs24\chcbpat17  et }}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs24\chcbpat17\cf1 moribus}}\plain \f2\scaps\lang1033\fs24\chcbpat17  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs24\chcbpat17\cf1 philosophorum}}\plain \f2\lang1033\fs24\cf1 . 112 Kurzbiographien mit Marginalien. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat17\cf1 De moribus et vita philosophorum veterum tractatura multa}}\plain \f2\i\lang1033\fs24\cf1  ... - ... ad Casdic regem Persarum etc. Deo gratias\plain \f2\lang1033\fs24\cf1 . Ed.: Gualteri\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 Burlaei\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 liber\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 de\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 vita\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 et\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 moribus\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 philosophorum.\plain \f1\fs24  Mit einer altspanischen \u220 \'dcbersetzung der Eskurialbibliothek, hg. von Hermann Knust (= Bibliothek des Litterarischen Vereins in Stuttgart 177), \plain \f2\lang1033\fs24\cf1 T\u252 \'fcbingen\plain \f1\fs24  1886, S. 1-278. \plain \f2\lang1033\fs24\cf1 Vgl. \plain \f1\fs24 Jan Prelog, Die \plain \f2\lang1033\fs24\cf1 Handschriften\plain \f1\fs24  und \plain \f2\lang1033\fs24\cf1 Drucke\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 von\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 Walter\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 Burleys\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 Liber\plain \f1\fs24  de \plain \f2\lang1033\fs24\cf1 vita\plain \f1\fs24  et \plain \f2\lang1033\fs24\cf1 moribus\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 philosophorum, Codices manuscripti\plain \f1\fs24  9 (1983), S. 1-18,\plain \f2\lang1033\fs24\cf1  (42\plain \f2\super\lang1033\fs32\cf1 va\plain \f2\lang1033\fs24\cf1 ) Schreibervermerk. {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat17\cf1 Nota. Secundum Orosium ab origine mundi ad urbem conditam fluxerunt anni 4484 et a condita urbe ad Christum anni 715. Ergo ab origine mundi ad Christum fluxerunt 5199. Et ita usque ad annum presentem scilicet 1383 fluxerunt, ab initio mundi 6582. Qui numerus distat a septem millenariis per 418 annos, infra quos mundus putat finem habiturus}}\plain \f2\i\lang1033\fs24\cf1 .}

