\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 209\plain \f0\super\fs32 va\plain \f0\fs24 -221\plain \f0\super\fs32 ra\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Thomas Palmeranus}}\plain \f1\b\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 De tribus punctis religionis Christianae}}\plain \f0\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Religio munda et immaculata aput deum hoc est visitare pupillos et viduas in tribulacione eorum et immaculatum se custodire ab hoc seculo. Iacobi Io dicens: Volens religionem aliquam intrare et eam observare}}\plain \f0\i\fs24  ... - ... nec nimis prolixium compilacionem decrevit. etc. Scriptum in brevis. Scriptum in Chrems per Petrum offerer schreyber an (Syben Manstat). Finis adest vere. etc. \plain \f0\fs24 Druck:\plain \f0\i\fs24  {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Hain}}\plain \f0\fs24  8544. Zur \u220 \'dcberlieferung vgl. Stegm\u252 \'fcller, RB, 8129, 1; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Bloomfield, in: Traditio 11 (1955)}}\plain \f0\fs24 , Nr. 859 (jeweils ohne diese Hs.).}

