\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 224\plain \f0\super\fs32 v\plain \f0\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Ps.-Ignatius Antiochenus}}\plain \f0\scaps\fs24 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Epistula ad B.M.V. ac responsio}}\plain \f0\fs24 . \plain \f0\i\fs24 Epistola Ignacii ad beatam virginem\plain \f0\fs24  \plain \f0\i\fs24 voluminis. Christifere Marie Ignatius suus. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Me neophitum Iohannisque tui discipulum confortare et consolare debueras}}\plain \f0\i\fs24  ... - ... sed valeat et exultet spiritus tuus in deo salutari tuo. Amen. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Stegm\u252 \'fcller, RB}}\plain \f0\fs24 , 165 und 165, 2. Drucke: Ignatii et Polycarpi epistulae, hg. von Theodor Zahn, Leipzig 1876, S. 299 f.; Patres apostolici, hg. von Franz Xaver Funk / Franz Diekamp, Bd 2, T\u252 \'fcbingen 1913, S. 321 f.}

