\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 1\plain \f0\super\fs32 r\plain \f0\fs24 -290\plain \f0\super\fs32 r\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Stenzel Bornbach}}\plain \f0\scaps\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Historia vom Aufruhr zu Danzig}}\plain \f0\fs24 . Dossier \u252 \'fcber die Danziger Konfessions- und Ratsstreitigkeiten 1522-1526 auf der Grundlage von Schriftst\u252 \'fccken, oft Briefen der Danziger Ratskanzlei, meist in deutscher \u220 \'dcbersetzung, manchmal auch zweisprachig. Zur \u220 \'dcberlieferung der Historia Stenzel Bornbachs vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Arnold, Historiographie, 1967}}\plain \f0\fs24 , S. 172 f.; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Bertling, Danziger Stadtbibliothek, 1892}}\plain \f0\fs24 , S. 46-48, 629 f., 726; {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Dworzaczkowa, Dziejopisarstwo [Geschichtsschreibung], 1962}}\plain \f0\fs24 , S. 18 f., 25 f., 36, 41; {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Gehrke, Das Ebert Ferber-Buch, 1892}}\plain \f0\fs24 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Gehrke, Wartzmann, 1900}}\plain \f0\fs24 ; {\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 G\u252 \'fcnther, Danziger Stadtbibliothek, 1903}}\plain \f0\fs24 , S. 42 f., 383 f., 430 f.; {\field{\*\fldinst HYPERLINK "hida://bezlit[6].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Mentzel-Reuters, Stadt und Welt, 2005}}\plain \f0\fs24 , S. 99-128, bes. S.  119 mit Anm. 76 (jeweils ohne diese Hs.).
