\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 Vor 1 und 9 fehlen je zwei Doppelbll., vor 76, 133, 217 und 219 fehlt je 1 Bl., vor 197 fehlen 4 Bll., am Ende der Hs. 2 Bll., I (abgel\u246 \'f6ster hinterer Spiegel) vorne eingelegt, bei vielen Rubrizierungen Farbe zerst\u246 \'f6rt, Bl. 84 bzw. 188 obere bzw. untere Ecke abgeschnitten (jeweils mit Textverlust), Bl. 264 verschmutzt (264\plain \f0\super\fs32 v\plain \f0\fs24  Textverlust), Bl. 64 unterer Blattrand abgeschnitten (geringer Textverlust), Bll. 159-160, 163, 179 untere Ecken, Bll. 110-114, 165-166 unterer Blattrand abgeschnitten, Bll. 195-196 am Au\u223 \'dfenrand angeschnitten, hintere Lagen lose \u8729 \'b7\plain \f2\fs24  \plain \f0\fs24 31 Zeilen (7\plain \f0\super\fs32 v\plain \f0\fs24 -8\plain \f0\super\fs32 v\plain \f0\fs24  30 Zeilen);\plain \f2\fs24  \plain \f0\fs24 2 Spalten \u8729 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Textualis}}\plain \f0\fs24  (mit Tendenz zur humanistischen Rotunda) von zwei H\u228 \'e4nden (1. Hand 1\plain \f0\super\fs32 r\plain \f0\fs24 -8\plain \f0\super\fs32 v\plain \f0\fs24 ); Reklamanten \u8729 \'b7 {\field{\*\fldinst HYPERLINK "hida://5705[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Quadratneumen}}\plain \f2\fs24  \plain \f0\fs24 \u8729 \'b7 Rubrizierung \u8729 \'b7\plain \f2\fs24  {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Lombarden}}\plain \f0\fs24  (rot, blau, Fadenrankenbesatz); {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Initialen}}\plain \f0\fs24  (Buchstabenk\u246 \'f6rper in Magenta, im Binnenfeld Akanthusranken, Besatzmotive stern- oder bl\u252 \'fctenf\u246 \'f6rmig, beides mehrfarbig); {\field{\*\fldinst HYPERLINK "hida://5270[2]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 historisierte Initialen}}\plain \f0\fs24  (derselbe Typ): 17\plain \f0\super\fs32 v\plain \f0\fs24  Christi Geburt, 19\plain \f0\super\fs32 v\plain \f0\fs24 