\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 \u1054 ?\u1090 ?\u1095 ?\u1077 ?\u1090 ? \u1048 ?\u1084 ?\u1087 ?\u1077 ?\u1088 ?\u1072 ?\u1090 ?\u1086 ?\u1088 ?\u1089 ?\u1082 ?\u1086 ?\u1081 ? \u1055 ?\u1091 ?\u1073 ?\u1083 ?\u1080 ?\u1095 ?\u1085 ?\u1086 ?\u1081 ? \u1073 ?\u1080 ?\u1073 ?\u1083 ?\u1080 ?\u1086 ?\u1090 ?\u1077 ?\u1082 ?\u1080 ? \u1079 ?\u1072 ? 1861 \u1075 ?\u1086 ?\u1076 ? [Jahresbericht der Kaiserlichen \u214 \'d6ffentlichen Bibliothek f\u252 \'fcr 1861], Sankt Petersburg 1862, S. 61 f., S. 93; Jean Baptiste Thibaut, Monuments de la notation ekphon\u233 \'e9tique et neumatique de l'\u233 \'e9glise latine, Sankt Petersburg 1912 (ND Hildesheim, Z\u252 \'fcrich [usw.] 1984), S. 74 f. (mit 2 Abb.); {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 \u1046 ?\u1080 ?\u1090 ?\u1086 ?\u1084 ?\u1080 ?\u1088 ?\u1089 ?\u1082 ?\u1072 ?\u1103 ?, \u1047 ?\u1072 ?\u1087 ?\u1072 ?\u1076 ?\u1085 ?\u1086 ?\u1077 ? \u1057 ?\u1088 ?\u1077 ?\u1076 ?\u1085 ?\u1077 ?\u1074 ?\u1077 ?\u1082 ?\u1086 ?\u1074 ?\u1100 ?\u1077 ? \u1074 ? \u1088 ?\u1091 ?\u1082 ?\u1086 ?\u1087 ?\u1080 ?\u1089 ?\u1103 ?\u1093 ?, 1957}}\plain \f0\fs24 , S. 304; {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Mokretsova / Shchegoleva, Catalogue, 2010}}\plain \f0\fs24 , S. 110-114, S. 281-284 (Cat. 49, 5 Abb.).   }

