\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 \u1058 ?\u1072 ?\u1090 ?\u1100 ?\u1103 ?\u1085 ?\u1072 ? \u1040 ?\u1083 ?\u1077 ?\u1082 ?\u1089 ?\u1077 ?\u1077 ?\u1074 ?\u1085 ?\u1072 ? \u1044 ?\u1086 ?\u1083 ?\u1075 ?\u1086 ?\u1076 ?\u1088 ?\u1086 ?\u1074 ?\u1072 ? [Tat'jana A. Dolgodrova], \u1056 ?\u1091 ?\u1082 ?\u1086 ?\u1087 ?\u1080 ?\u1089 ?\u1085 ?\u1099 ?\u1077 ? \u1073 ?\u1091 ?\u1088 ?\u1075 ?\u1091 ?\u1085 ?\u1076 ?\u1089 ?\u1082 ?\u1080 ?\u1077 ? \u1095 ?\u1072 ?\u1089 ?\u1086 ?\u1089 ?\u1083 ?\u1086 ?\u1074 ?\u1099 ? XV \u1074 ?\u1077 ?\u1082 ?\u1072 ? \u1074 ? \u1089 ?\u1086 ?\u1073 ?\u1088 ?\u1072 ?\u1085 ?\u1080 ?\u1103 ?\u1093 ? \u1057 ?\u1057 ?\u1057 ?\u1056 ? [Handgeschriebene Burgundische Stundenb\u252 \'fccher des 15. Jhs. in den Best\u228 \'e4nden der UdSSR], in: \u1060 ?\u1077 ?\u1076 ?\u1086 ?\u1088 ?\u1086 ?\u1074 ?\u1089 ?\u1082 ?\u1080 ?\u1077 ? \u1095 ?\u1090 ?\u1077 ?\u1085 ?\u1080 ?\u1103 ? 1979, Moskau 1982, S. 125-138; {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Zolotova, Enluminures}}\plain \f0\fs24 , 1991, Repr. 87-95; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Mokretsova / Shchegoleva, Catalogue, 2010}}\plain \f0\fs24 , S. 180-182, 336 f. (Cat. 116, 4 Abb.).}

