\par \pard\fi0\li0\tx2160\tx2700\qj\ri0\sb0\sa0\itap0 14\plain \f0\super\fs32 v\plain \f0\fs24 -482\plain \f0\super\fs32 r\plain \f0\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Valerius Maximus}}\plain \f0\scaps\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Factorum et dictorum memorabilium libri novem}}\plain \f0\fs24 . B\u252 \'fccher V-XI. 1375 im Auftrag Karls V. von Frankreich ins Franz\u246 \'f6sische \u252 \'fcbersetzt durch {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Simon de Hesdin}}\plain \f0\fs24  und {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Nicolas de Gonesse}}\plain \f0\fs24 . \plain \f0\i\fs24 Faits et dits m\u233 \'e9morables\plain \f0\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Cy commence d'altruit}}\plain \f0\i\fs24  ... - ... Et fut finer \plain \f0\fs24 [!]\plain \f0\i\fs24 , l'an mil CCCC et ving la veille de monseigneur Saint Michel archange \plain \f0\fs24 [1420 X  15]. \plain \f0\i\fs24 Et sic est finis huius hystorie videlicet Valeriani Maximiniani. Explicit. \plain \f0\fs24 Vgl. Catalogus translationum et commentariorum. Mediaeval and Renaissance Latin Translations and Commentaries. Annotated Lists and Guides, Bd. 5, bearb. von Paul Oskar Kristeller, Washington D.C. 1984, S. 298 f., 318 f. 482\plain \f0\super\fs32 v\plain \f0\fs24 -485\plain \f0\super\fs32 v\plain \f0\fs24  leer.}

