\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 Vor 17, 40, 44, 50, 52, 55, 57, 67, 85, 91 und 135 fehlt je ein Bl. (mit Verlust von Text, vielleicht auch von Miniaturen) \u183 \'b7 1 (vorderer Vorsatz), 2-136, 137 (hinterer Vorsatz) \u183 \'b7 19 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Bastarda}}\plain \f0\fs24  (mit Schleifen) einer Hand \u183 \'b7 Rubrizierung \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5270[3]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Zeilenf\u252 \'fcllung}}\plain \f0\fs24  (Fleuron\u233 \'e9est\u228 \'e4be in Kreissegment- und S\u228 \'e4geblattform, in Blau und Gold); {\field{\*\fldinst HYPERLINK "hida://5270[2]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Initialen}}\plain \f0\fs24  (Emailtyp, Bl\u252 \'fctenranken und Rosetten im Binnenfeld, wei\u223 \'dfe Fadenranken als Stammf\u252 \'fcllung); {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Silhouetten-Initialen}}\plain \f0\fs24  (teilweise in Gold, mit Fleuronn\u233 \'e9e-Fadenbesatz, rot oder blau); {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Teilbord\u252 \'fcre}}\plain \f0\fs24  (Dornblatt-Fadenranken mit Bl\u252 \'fcten, Lanzettbl\u228 \'e4ttern und Goldpollen, vertikal oder \u252 \'fcber Eck f\u252 \'fchrend).}

