\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f0\super\fs32 r\plain \f0\fs24 )\plain \f0\scaps\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Anastasius Bibliothecarius}}\plain \f0\scaps\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Epistola ad Petrum episcopum Gavimensem}}\plain \f0\scaps\fs24 . \plain \f0\fs24 Prolog zum nachfolgenden Werk. \plain \f0\i\fs24 Incipit epistola Anastasii apostolice sedis bibliothecarii. Petro e regione sancte Savinensis ecclesie episcopo Athanasius summe et apostolice sedis bibliothecarius in domino salutem. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Post translatam a me ad peticionem tue sanctitatis passionem precipui doctoris ac martyris Petri Alexandrine urbis patriarche}}\plain \f0\i\fs24  ... - ... ac pro nobis semper orare dignetur. Amen. \plain \f0\fs24 Druck: Acta Sanctorum Iunii, Bd. 4, Antwerpen 1707, S. 182; ND: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 MPL}}\plain \f0\fs24  129, Sp. 743A-744A,}

