\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 \u1047 ?\u1054 ?\u1056 ?}}\plain \f0\fs24  16 (1954), S. 171, Nr. 368; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 \u1046 ?\u1080 ?\u1090 ?\u1086 ?\u1084 ?\u1080 ?\u1088 ?\u1089 ?\u1082 ?\u1072 ?\u1103 ?, \u1047 ?\u1072 ?\u1087 ?\u1072 ?\u1076 ?\u1085 ?\u1086 ?\u1077 ? \u1057 ?\u1088 ?\u1077 ?\u1076 ?\u1085 ?\u1077 ?\u1074 ?\u1077 ?\u1082 ?\u1086 ?\u1074 ?\u1100 ?\u1077 ? \u1074 ? \u1088 ?\u1091 ?\u1082 ?\u1086 ?\u1087 ?\u1080 ?\u1089 ?\u1103 ?\u1093 ?, 1957}}\plain \f0\fs24 , S. 288; Charles L. Stinger, Humanism and the Church Fathers. Ambrogio Traversari (1386-1439) and Christian Antiquity in the Italian Renaissance, Albany 1977, S. 129 f., 269 mit Anm. 168; Chronicon monasterii Casinensis, hg. von Hartmut Hoffmann (MGH SS 34), Hannover 1980, S. 609; {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Kristeller, Iter italicum, 1990}}\plain \f0\fs24 , S. 199 f.; Virginia Brown, Ambrogio Traversari\rquote s Revision of the Chronicon Casinense and the Dialogi de Miraculis S. Benedicti. The Oldest Manuscripts Rediscovered, Medieval Studies 58 (1996), S. 291-338; ND in: Dies., Terra Sancti Benedicti. Studies in Paleaography, History and Liturgy of Medieval Southern Italy (\plain \f1\lang1033\fs24\cf1 Storia e letteratura 219), Rom 2005, S. 51-64, bes. S. 51-53;\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 \u1059 ?\u1082 ?\u1072 ?\u1079 ?\u1072 ?\u1090 ?\u1077 ?\u1083 ?\u1100 ?}}\plain \f0\fs24 , 1996, S. 24; \u1045 ?\u1082 ?\u1072 ?\u1090 ?\u1077 ?\u1088 ?\u1080 ?\u1085 ?\u1072 ? \u1070 ?\u1088 ?\u1100 ?\u1077 ?\u1074 ?\u1085 ?\u1072 ? \u1047 ?\u1086 ?\u1083 ?\u1086 ?\u1090 ?\u1086 ?\u1074 ?\u1072 ?, \u1060 ?\u1083 ?\u1086 ?\u1088 ?\u1077 ?\u1085 ?\u1090 ?\u1080 ?\u1081 ?\u1089 ?\u1082 ?\u1072 ?\u1103 ? \u1084 ?\u1080 ?\u1085 ?\u1080 ?\u1072 ?\u1090 ?\u1102 ?\u1088 ?\u1072 ? XV \u1074 ?. \u1074 ? \u1089 ?\u1086 ?\u1073 ?\u1088 ?\u1072 ?\u1085 ?\u1080 ?\u1103 ?\u1093 ? \u1052 ?\u1086 ?\u1089 ?\u1082 ?\u1074 ?\u1099 ? [Eine florentinische Miniatur des 15. Jhs. in Moskauer Sammlungen], \u1042 ?\u1077 ?\u1089 ?\u1090 ?\u1085 ?\u1080 ?\u1082 ? \u1080 ?\u1089 ?\u1090 ?\u1086 ?\u1088 ?\u1080 ?\u1080 ? \u1083 ?\u1080 ?\u1090 ?\u1077 ?\u1088 ?\u1072 ?\u1090 ?\u1091 ?\u1088 ?\u1099 ?, \u1080 ?\u1089 ?\u1082 ?\u1091 ?\u1089 ?\u1089 ?\u1090 ?\u1074 ?\u1072 ?, Bd. 3, Moskau 2006, S. 453-463; {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Mokretsova / Shchegoleva, Catalogue, 2010}}\plain \f0\fs24 , S. 108 f., 280 f. (Cat. 47, 1 Abb.).}

