\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs24 Vor 3 zwei Bll. ausgeschnitten \u183 \'b7 Schreiberfoliierung I-XCV \u183 \'b7 12 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Rotunda}}\plain \f1\fs24  (stilisiert) einer Hand \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5705[0]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Quadratneumen}}\plain \f1\fs24  \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Flechtbandinitialen}}\plain \f1\fs24  (\u252 \'fcber 7 Zeilen, einfarbig, Gittergeflechtbesatz, teilweise mit Gesichtskonturen); weitere Initialen (\u252 \'fcber 3 Zeilen, mehrfarbig, mit Akanthusranken, schwarz-wei\u223 \'df oder rot-wei\u223 \'df, bzw. dickem Taugeflecht im Binnenfeld); Initialen (\u252 \'fcber 1 Zeile, in Gold, auf blauem oder purpurfarbenem Grund); 1\plain \f1\super\fs32 r\plain \f1\fs24  und 43\plain \f1\super\fs32 v \plain \f1\fs24 Flechtbandinitialen (gro\u223 \'df, rot-blau, mit Gittergeflecht und gr\u252 \'fcnem Akanthus-Besatz); 2\plain \f1\super\fs32 r\plain \f1\fs24  {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 historisierte Initiale:}}\plain \f1\fs24  K\u246 \'f6nig David (betend, neben ihm Krone und Harfe, \u252 \'fcber ihm schwebend Engel mit Schwert, Besatz aus Palmettenranken und einer Maske, lila Polstergrund, mit Rahmen und Fadenranken, beides in Gold); 14\plain \f1\super\fs32 v\plain \f1\fs24  Initiale (\u252 \'fcber 3 Zeilen, zwei Masken, Polstergrund purpurfarben, mit goldenen Fadenranken und Dreipunktmuster); 44\plain \f1\super\fs32 r {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Initiale}}\plain \f1\fs24  (\u252 \'fcber 7 Zeilen, blau, mit roten Palmetten und wei\u223 \'dfen Flechtbandknoten als Stammf\u252 \'fcllung, Polstergrund aus wei\u223 \'df-roten Palmettenranken, im Binnenfeld Palmettenbl\u228 \'e4tter).}

