\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f0\super\fs32 r\plain \f0\fs24 -42\plain \f0\super\fs32 v\plain \f0\fs24 )\plain \f0\super\fs32  \plain \f0\fs24 F\u252 \'fcr die Vesper der Osterzeit sonntags bis mittwochs. \plain \f0\i\fs24 Incipit prima pars psalterii vespertinii, a dominica usque ad feriam quartam inclusibe anno 1607. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Dixit dominus seculorum. Amen}}\plain \f0\i\fs24  ... - ... In diebus ferialibus tempore Paschali. Antiphona. Alleluia seculorum. Amen\plain \f0\fs24 , (43\plain \f0\super\fs32 r\plain \f0\fs24 )  leer, (43\plain \f0\super\fs32 v\plain \f0\fs24 -93\plain \f0\super\fs32 v\plain \f0\fs24 ) F\u252 \'fcr die Vesper der Osterzeit donnerstags bis samstags. \plain \f0\i\fs24 Incipit secunda pars psalteriii vespertinii, a feria V\plain \f0\i\super\fs32 a\plain \f0\i\fs24  usque ad sabbathum inclusive anno 1607. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Et omnis seculorum. Psalmus 131}}\plain \f0\i\fs24  ... - ... In sabbathis tempore Paschali. Antiphona. }

