\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24 181\plain \f0\super\fs32 r\plain \f0\fs24 -206\plain \f0\super\fs32 v\plain \f0\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Simon Favershamensis}}\plain \f0\scaps\fs24 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Quaestiones super libros priorum Analyticorum}}\plain \f0\scaps\fs24 . \plain \f0\fs24 Titel und Nummern der 17.-19. Quaestio fehlen, Platz ausgespart. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Queritur primo circa principium primi libri priorum. Utrum de syllogismo simpliciter possit esse aliqua sciencia}}\plain \f0\i\fs24  ... - ... qui sic partum in alia et huiustam \plain \f0\fs24 [!] \plain \f0\i\fs24 est, queritur non idem. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Lohr, Commentaries, 1973}}\plain \f0\fs24 , S. 142 f., Nr. 4.}

