\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24 244\plain \f0\super\fs32 r\plain \f0\fs24 -248\plain \f0\super\fs32 r\plain \f0\i\fs24  \plain \f0\fs24 [{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17\cf1 Johannes a Polonia}}\plain \f1\lang1033\fs24\cf1 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17\cf1 Computus manualis}}\plain \f1\scaps\lang1033\fs24\cf1 .\plain \f1\b\lang1033\fs24\cf1  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Assit puero sancta Maria nato. Notandum, quod duplex sit cyclus}}\plain \f0\i\fs24   ... - ... Considerandum est, (quod) quocumque (..va) erit via (cunctorum) cyclorum lunarum. \plain \f0\fs24 Wohl ein Auftragswerk des Bischofs von Hildesheim an die Universit\u228 \'e4t Leipzig, den Kalender f\u252 \'fcr 1444 zu berechnen. Vgl. Leipzig, UB, Cod. 1441. 248\plain \f0\super\fs32 v\plain \f0\fs24  Federproben. Andere Hand.}

