\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 70\plain \f0\super\fs32 r\plain \f0\fs24 -86\plain \f0\super\fs32 v\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Giordano Bruno}}\plain \f0\scaps\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 De magia mathematica}}\plain \f0\scaps\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Influit deus in angelos, angeli in corpora c\u230 \'e6lestia, c\u230 \'e6lestia in elementa}}\plain \f0\i\fs24  ... - ... et ad rem minus facientia plurimum miscuere, fortasse ut artem minus perviam facerent, quod nos fecisse potuimus. Finis. \plain \f0\fs24 Exzerpte aus {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Johannes Trithemius}}\plain \f0\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Agrippa von Nettesheim, Heinrich Cornelius}}\plain \f0\fs24  und {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Ps.-Albertus Magnus}}\plain \f0\fs24 . Ed. (mit vielen Lesel\u252 \'fccken): {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Bruno, Opera, Bd. 3, 1891}}\plain \f0\fs24 , S. 492-506. 86a\plain \f0\super\fs32 rv\plain \f0\fs24  leer.}

