\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 VII
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 17\plain \f0\super\fs32 rv\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 David Chytr\u228 \'e4us}}\plain \f0\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Brief}}\plain \f0\fs24  an {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100gi/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Johann Lange}}\plain \f0\scaps\fs24 , \plain \f0\fs24 Professor in K\u246 \'f6nigsberg\plain \f0\scaps\fs24 .\plain \f0\fs24  \u220 \'dcber eine Empfehlung an die Akademie Heidelberg (o.O., 1578 I 2). {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Clarissimo viro M. Iohanni Langio, Professori in Paedagogia Academi\u230 \'e6 Regiomontani, amico carissimo. K\u246 \'f6nigsberg. S.D. Clarissime vir, amice carissime. Filium dei, a cuius Genotbliis annum novum in ecclesia exorsi sumus, toto prectore precor}}\plain \f0\i\fs24  ... - ... Bene vale. Postridie Cal. Ianuarii inchoante annum 1578. \plain \f0\fs24 Zu den Briefen von Chytr\u228 \'e4us vgl. J\u252 \'fcrgen Leonhardt, Der lateinische Briefstil in den Briefen des David Chytraeus, in: \plain \f1\lang1033\fs24\cf1 Humanismus\plain \f0\fs24  \plain \f1\lang1033\fs24\cf1 im\plain \f0\fs24  \plain \f1\lang1033\fs24\cf1 Norden. F\plain \f0\fs24 r\u252 \'fchneuzeitliche Rezeption antiker Kultur und Literatur an Nord- und Ostsee, hg. von Thomas Haye (Chlo\u235 \'eb 32), \plain \f1\lang1033\fs24\cf1 Amsterdam [u.a.]\plain \f0\fs24  2000, S. 135-156.}

