\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 X
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 20\plain \f0\super\fs32 r\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Wilhelm Gnapheus}}\plain \f0\scaps\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Carmen}}\plain \f0\scaps\fs24  de effigie {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Alberti ducis Prussiae}}\plain \f0\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Albertus D.Ci. Marchi Brandenburgensi et primus dux Prussiae, amico lectori. Quid  te suspensum tenet haec pictura viator}}\plain \f0\i\fs24  ... - ... His terris primum me statuere ducem. Anno \plain \f0\fs24 [15]\plain \f0\i\fs24 41. Manus Gnaphaei. \plain \f0\fs24 Weder in: \plain \f1\lang1033\fs24\cf1 Albert Reusch, \plain \f0\fs24 Wilhelm Gnapheus, erster Rector des Elbinger Gymnasiums, 2 Teile (Elbing, Gymnasium, Schulprogramme 1867/68 bzw. 1876/77), \plain \f1\lang1033\fs24\cf1 Elbing 1868,\plain \f0\fs24  1877, noch in: Urkundenbuch zur Reformationsgeschichte des Herzogthums Preu\u223 \'dfen, hg. von Paul Tschackert, Bd. 2-3\plain \f1\lang1033\fs24\cf1  (\plain \f0\fs24 Publicationen aus den K\u246 \'f6niglich Preu\u223 \'dfischen Staatsarchiven 44, 45), Leipzig 1890 (ND \plain \f1\lang1033\fs24\cf1 Osnabr\u252 \'fcck\plain \f0\fs24  1965), hier Bd. 3, S. 301 (s.n. Gnapheus), 333 f. (s.n. Gnapheus), oder in: Theodor Wotschke, Herzog Albrecht von Preu\u223 \'dfen und Wilhelm Gnapheus. Ein Nachtrag, Archiv f\u252 \'fcr Reformationsgeschichte 27 (1930), S. 122-131, enthalten. 20\plain \f0\super\fs32 v\plain \f0\fs24 -21\plain \f0\super\fs32 v\plain \f0\fs24  leer.}

