\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs24 XIV
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 27\plain \f1\super\fs32 rv\plain \f1\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\fs24\chcbpat17 Axel Gustafsson Oxenstierna af S\u246 \'f6derm\u246 \'f6re}}\plain \f1\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Brief}}\plain \f1\fs24 . Entsendung des preu\u223 \'dfischen Ingenieurs {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100gi/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Heinrich Thomae}}\plain \f1\fs24  an {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100gi/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Andreas Erichson}}\plain \f1\fs24 , Gouverneur von Riga (W\u252 \'fcrzburg, 1633 II 25). \plain \f1\i\fs24 Doupplette. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\fs24\chcbpat17 Edler Vetter, Insonders Freundtlichgeliebter, Herr Gouverneur. Bhatt mich Burgermeister und Ratsherr durch Durchl\u252 \'fcchtiger Unter anderen}}\plain \f1\i\fs24  ... - ... Datum W\u252 \'fcrtzburgk den 25. Februarii Anno 1633. Des Herrn Axell Ocksenstiernus. \plain \f1\fs24 Briefadresse. \plain \f1\i\fs24 Dem edlen und Werten, meinem insbesonders geliebten Freundt, Andreass Erich\u223 \'dfon, der K\u246 \'f6niglichen Erlauchteten zur Schweden bestalten Gouverneur in der Nehrungen Dinge\plain \f1\fs24 .\plain \f1\i\fs24  \plain \f1\fs24 Nicht\plain \f1\i\fs24  \plain \f2\lang1033\fs24\cf1 in: Gabriel\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 Gustafsson\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 Oxenstjernas\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 bref\plain \f1\fs24  \plain \f2\lang1033\fs24\cf1 1611\plain \f1\fs24 -\plain \f2\lang1033\fs24\cf1 1640\plain \f1\fs24  (Rikskansleren Axel Oxenstjernas Skrifter och brefvexling, Abtlg. 2, Bd. 3,1), Stockholm 1890, enthalten.}

