\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 262\plain \f0\super\fs32 r\plain \f0\fs24 -269\plain \f0\super\fs32 v\plain \f0\fs24  \plain \f1\scaps\lang1033\fs24 Fragments de quelques {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Sermons du petit p\u232 \'e8re Andr\u233 \'e9}}\plain \f1\scaps\lang1033\fs24 , religieux augustin r\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 form\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24  de la communaut\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24  de Bourges. \plain \f0\i\fs24 Andr\u233 \'e9 Boulanger religieux augustin est trop conn\u251 \'fb dans le monde \u8230 \'85 nous n\rquote avons de luy aucun ouvrage imprim\u233 \'e9 \u8230 \'85 il mourut a Paris dans le couvent de la reine Marguerite au fauxbourg Saint Germain, l\rquote an 1654, ag\u233 \'e9 de 49 ans \u8230 \'85 - \u8230 \'85 et il continua, sans que personne s\rquote app\u232 \'e8rc\u251 \'fbt de son manqu\u233 \'e9 de m\u233 \'e9moire\plain \f0\fs24 . Druck als Vorlage? Vgl. Andr\u233 \'e9 de Boulanger, Oraison fun\u232 \'e8bre sur la mort de Marie de Lorraine, abbesse du royal monast\u232 \'e8re de Chelles, avec le testament de ladite dame, Paris 1627.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Times New Roman;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red224\green224\blue224;}

