\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 270\plain \f0\super\fs32 r\plain \f0\fs24 -279\plain \f0\super\fs32 r\plain \f0\fs24  \plain \f1\scaps\lang1033\fs24 Recueil curieux des principaux endroits du livre intitul\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 La vie des trois Maries}}\plain \f1\scaps\lang1033\fs24 . \plain \f0\i\fs24 Le roman des trois Maries en rithme fran\u231 \'e7oise fut compose vers le milieu du XIV si\u232 \'e8cle par religieux personne, fr\u232 \'e8re Jean Ven\u234 \'eatte de l\rquote ordre des Carmes, native du pays de Picardie \u8230 \'85 imprim\u233 \'e9e a Paris en 1511 \u8230 \'85 - \u8230 \'85 mais je crois devoir terminer icy mon extrait et ne pas perdre des instans que je puis employer a faire connoitre Jean Ven\u232 \'e8tte et son genre de po\u232 \'e8sie. \plain \f0\fs24 Druck als Vorlage? Vgl. Jean de Venette, \plain \f1\lang1033\fs24\cf1 La vie des trois Maries, de leur m\u232 \'e8re, de leurs enfans, et de leurs maris. Compos\u233 \'e9e en rime fran\u231 \'e7oise par Jean\plain \f1\b\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 de Venette et translat\u233 \'e9 de rime en prose par Jean\plain \f1\b\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 Drouyn, Troyes um 1600.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Times New Roman;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red224\green224\blue224;}

