\pard\fi0\li0\tx2160\tx2700\qj\ri0\sb0\sa0\itap0 \plain \f0\fs24 Vor 1 fehlen 2 Bll. \u8729 \'b7 Foliierung I (vorderer Vorsatz, Papier), 1-189, II (hinterer Vorsatz, Papier) \u8729 \'b7 13 Zeilen \u8729 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Bastarda}}\plain \f0\fs24  einer Hand \u8729 \'b7 Rubrizierung \u8729 \'b7 {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Satz-Lombarden}}\plain \f0\fs24  (in Gold, roter oder blauer Grund mit goldenen Fadenranken); {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Zeilenf\u252 \'fcllung}}\plain \f0\fs24  (rot oder blau, mit goldenen geometrischen Mustern oder Wellenlinien); {\field{\*\fldinst HYPERLINK "hida://5270[2]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Vollbord\u252 \'fcren}}\plain \f0\fs24  (auf Bll. mit Miniaturen, Faden- und Akanthusranken, mit Bl\u252 \'fcten, Bl\u228 \'e4ttern und Fr\u252 \'fcchten, manchmal zus\u228 \'e4tzlich mit V\u246 \'f6geln, auf goldenem Grund oder auf Feldern verschiedener Form, teilweise vergoldet); Bord\u252 \'fcrenst\u228 \'e4be (gleicher Typ, ohne V\u246 \'f6gel); {\field{\*\fldinst HYPERLINK "hida://5270[3]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Initialen}}\plain \f0\fs24  (Buchstabenk\u246 \'f6rper blau, mit Ranken und "Banderolen" im Camaieu-Stil, oder rot, mit goldenen Ranken, Polstergrund rot, mit goldenen Bl\u252 \'fctenranken, oder blau, mit wei\u223 \'dfen Ranken); {\field{\*\fldinst HYPERLINK "hida://5270[4]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Miniaturen}}\plain \f0\fs24 : 20\plain \f0\super\fs32 r\plain \f0\fs24  Mari\u228 \'e4 Verk\u252 \'fcndigung, 38\plain \f0\super\fs32 r\plain \f0\fs24  Mari\u228 \'e4 Heimsuchung, 56\plain \f0\super\fs32 r\plain \f0\fs24  Kreuzigung, 58\plain \f0\super\fs32 r\plain \f0\fs24  Pfingsten, 60\plain \f0\super\fs32 r\plain \f0\fs24  Christi Geburt, 69\plain \f0\super\fs32 v\plain \f0\fs24  Verk\u252 \'fcndigung an die Hirten, 76\plain \f0\super\fs32 v\plain \f0\fs24  Anbetung der K\u246 \'f6nige, 82\plain \f0\super\fs32 v\plain \f0\fs24  Darstellung des Herrn, 88\plain \f0\super\fs32 v\plain \f0\fs24  Flucht nach \u196 \'c4gypten, 99\plain \f0\super\fs32 r\plain \f0\fs24  Mari\u228 \'e4 Kr\u246 \'f6nung, 107\plain \f0\super\fs32 r\plain \f0\fs24  Bathseba und K\u246 \'f6nig David; Kleinbilder (\u252 \'fcber 5 Zeilen): 11\plain \f0\super\fs32 r\plain \f0\fs24  Johannes der Evangelist, 13\plain \f0\super\fs32 r\plain \f0\fs24  Lukas, 15\plain \f0\super\fs32 v\plain \f0\fs24  Matth\u228 \'e4us, 18\plain \f0\super\fs32 r\plain \f0\fs24  Markus; 182\plain \f0\super\fs32 r\plain \f0\fs24  Dreifaltigkeit, 183\plain \f0\super\fs32 r\plain \f0\fs24  Johannes der T\u228 \'e4ufer (mit Lamm und Buch), 183\plain \f0\super\fs32 r\plain \f0\fs24  Johannes der Evangelist (ohne Adler, mit Kelch), 184\plain \f0\super\fs32 v\plain \f0\fs24  Petrus und Paulus, 185\plain \f0\super\fs32 r\plain \f0\fs24  Stephan, 186\plain \f0\super\fs32 r\plain \f0\fs24  Sebastian, 187\plain \f0\super\fs32 r\plain \f0\fs24  Antonius, 188\plain \f0\super\fs32 r\plain \f0\fs24  Anna (mit Maria als kleinem M\u228 \'e4dchen), 189\plain \f0\super\fs32 r\plain \f0\fs24  Katharina.}

