\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 (19\plain \f0\super\fs32 r\plain \f0\fs24 -28\plain \f0\super\fs32 r\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Mariengebete}}\plain \f0\fs24 , (19\plain \f0\super\fs32 r\plain \f0\fs24 -21\plain \f0\super\fs32 v\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Leroquais, Les livres d'heures. Manuscrits, Bd. 2}}\plain \f0\fs24 , S. 346 f., Nr. XXXVIII (maskuline Form), (24\plain \f0\super\fs32 r\plain \f0\fs24 -28\plain \f0\super\fs32 r\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Leroquais, Les livres d'heures. Manuscrits, Bd. 2}}\plain \f0\fs24 , S. 336 f., Nr. XXI (maskuline Form), (19\plain \f0\super\fs32 v\plain \f0\fs24 -28\plain \f0\super\fs32 v\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Gebete}}\plain \f0\fs24 . 2. Hand, (19\plain \f0\super\fs32 v\plain \f0\fs24 -20\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio ad gloriosam virginem Mariam ante sacram coronationem. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Sanctissima et incontaminata virgo Maria, deprecor te per illud donum castititatis}}\plain \f0\i\fs24  ... - ... atque in celesti regno electis eius sociari. Qui vivit et regnat in secula seculorum. Amen. Pater noster. Ave Maria\plain \f0\fs24 , (20\plain \f0\super\fs32 v\plain \f0\fs24 -21\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Sequuntur \plain \f0\fs24 [78]\plain \f0\i\fs24  nomina domini nostri Iesu Christi. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Quicumque portaverat, ab omni malo liberabitur. Trinitas, Agios, Soter, Messias}}\plain \f0\i\fs24  ... - ... Redemptor, Unitas, Summum, Bonum, Unam. Amen\plain \f0\fs24 , (21\plain \f0\super\fs32 v\plain \f0\fs24 ) Blatt am oberen Rand beschnitten (Textverlust). \plain \f0\i\fs24 ... sagittas etc. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Coniuro vos, omnia tela nequissima omnesque ea ferentia per flagellationem domini nostri Iesu Christi}}\plain \f0\i\fs24  ... - ... nec in aliquo l\u230 \'e6dere possitis per sanctam trinitatem. Amen\plain \f0\fs24 , (21\plain \f0\super\fs32 v\plain \f0\fs24 -22\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio devotissima. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666v/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Jesus en croix, filz de dieu le pere omnipotent, toy qui est dieu des anges}}\plain \f0\i\fs24  ... - ... je vieux commander mon corps et mon ame. Pere Nostre etc. Amen. \u8224 \'86. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Sonet, R\u233 \'e9pertoire, 1956}}\plain \f0\fs24 , Nr. 945, (23\plain \f0\super\fs32 rv\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio devotissima. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666v/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Jesus, roy de tout le monde, en qui toute bonte abunde}}\plain \f0\i\fs24  ... - ... le faux et aporter et malle bouche. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Sonet, R\u233 \'e9pertoire, 1956}}\plain \f0\fs24 , Nr. 987,\plain \f0\i\fs24  \plain \f0\fs24 (24\plain \f0\super\fs32 v\plain \f0\fs24 -28\plain \f0\super\fs32 r\plain \f0\fs24 )\plain \f0\i\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666v/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Et que ne puysse par telle connyse estre deceu par convoitise}}\plain \f0\i\fs24  ... - ... qu'en peche ne puisse mourir aussi soit il. Amen. Jesus\plain \f0\fs24 , (28\plain \f0\super\fs32 v\plain \f0\fs24 -29\plain \f0\super\fs32 v\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666v/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Glorieuse vierge Marie, mere de Jesu Christ, vray dieu tout puissant, royne tres precieuse}}\plain \f0\i\fs24  ... - ... que tu veilles avoir pour recommandez mon corps et mon ame. Amen. Jesus. {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Sonet, R\u233 \'e9pertoire, 1956}}\plain \f0\fs24 , Nr. 680,\plain \f0\i\fs24  }

