\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 (29\plain \f0\super\fs32 r\plain \f0\fs24 -49\plain \f0\super\fs32 v\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Officium BMV}}\plain \f0\fs24 . 1. Teil, (29\plain \f0\super\fs32 r\plain \f0\fs24 -39\plain \f0\super\fs32 r\plain \f0\fs24 ) Matutin, (31\plain \f0\super\fs32 r\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Chevalier, Repertorium, 1892-1921}}\plain \f0\fs24 , Nr. 16154, (39\plain \f0\super\fs32 v\plain \f0\fs24 -49\plain \f0\super\fs32 v\plain \f0\fs24 ) Laudes, (47\plain \f0\super\fs32 rv\plain \f0\fs24 ) Capitulum nach dem Gebrauch von Bourges, Metz, Sarum und Tours, (49\plain \f0\super\fs32 rv\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Chevalier, Repertorium, 1892-1921}}\plain \f0\fs24 , Nr. 13037, (49\plain \f0\super\fs32 v\plain \f0\fs24 ) Bricht ab \plain \f0\i\fs24 >Responsorium<. Quod operatus es in nobis\plain \f0\fs24 , (29\plain \f0\super\fs32 r\plain \f0\fs24 -33\plain \f0\super\fs32 r\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Gebete}}\plain \f0\fs24 . 2. Hand. \plain \f0\i\fs24 Oratio devotissima ex sanctis Augustino et Cypriano. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 O domine Iesu \u8224 \'86, per nomen sanctum tuum custodi me}}\plain \f0\i\fs24  ... - ... per omnia secula seculorum. \u8224 \'86 Amen \u8224 \'86 Iesus \u8224 \'86\plain \f0\fs24 , (33\plain \f0\super\fs32 v\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Chevalier, Repertorium, 1892-1921}}\plain \f0\fs24 , Nr. 2084. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 AH}}\plain \f0\fs24  30, S. 240, Nr. 126, (34\plain \f0\super\fs32 r\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Ablassgebet}}\plain \f0\fs24 . \plain \f0\i\fs24 Oratio domini Xisti pape, qui concessit eam devote dicentibus XI mili\u230 \'e6 annorum indulgenti\u230 \'e6. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Ave, sanctissima Maria}}\plain \f0\i\fs24  ... - ... regnat in se\plain \f0\fs24 [cula seculorum]. \plain \f0\i\fs24 Amen. \plain \f0\fs24 Vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 1, S. 299, 336. Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Haimerl, Gebetbuchliteratur, 1952}}\plain \f0\fs24 , S. 62 (324), 92 f. (555), 121 (711), (34\plain \f0\super\fs32 r\plain \f0\fs24 -35\plain \f0\super\fs32 r\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Kommuniongebet}}\plain \f0\fs24 . \plain \f0\i\fs24 Oratio devota ante communionem \u8224 \'86. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Ne irascaris, queso, domine }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 [Gen 18,32]}}\plain \f0\i\fs24  ... - ... per omnia secula seculorum. Amen. {\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Haimerl, Gebetbuchliteratur, 1952}}\plain \f0\fs24 , S. 91 (537), (35\plain \f0\super\fs32 r\plain \f0\fs24 -39\plain \f0\super\fs32 v\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Gebete}}\plain \f0\fs24 . \plain \f0\i\fs24 Sequuntur 5 orationes de doloribus beat\u230 \'e6 Mari\u230 \'e6 virginis valde devota. \plain \f0\fs24 Vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 2, S. 26 f., 61. Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[6].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Haimerl, Gebetbuchliteratur, 1952}}\plain \f0\fs24 , S. 92 (549), (35\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio prima. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Mediatrix dei}}\plain \f0\i\fs24  ... - ... periculis pr\u230 \'e6sentibus et futuris. Amen\plain \f0\fs24 , (35\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio \plain \f0\fs24 [2]\plain \f0\i\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Auxiliatrix dei}}\plain \f0\i\fs24  ... - ... diligentius servivissem. Amen. Iesus\plain \f0\fs24 , (36\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio 3. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Reparatrix debilium}}\plain \f0\i\fs24  ... - ... malis in perpetuum tueatur. Amen. Iesus\plain \f0\fs24 , (36\plain \f0\super\fs32 v\plain \f0\fs24 -37\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio 4. {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Illuminatrix cecorum}}\plain \f0\i\fs24  ... - ... su\u230 \'e6 sacratissim\u230 \'e6 passionis. Amen. Iesus\plain \f0\fs24 , (37\plain \f0\super\fs32 rv\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio 5. Adiuvatrix omnium ... - ... in secula seculorum. Amen. Iesus\plain \f0\fs24 , (37\plain \f0\super\fs32 v\plain \f0\fs24 -38\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio sancti Augustini devota. \plain \f0\fs24 Vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 1, S. 280. Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[7].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Haimerl, Gebetbuchliteratur, 1952}}\plain \f0\fs24 , S. 73 (405), 87 (512), 91 (539), 103 (601), 105 (611), 113 (655), 126 (774).\plain \f0\i\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Deus propitius esto}}\plain \f0\i\fs24  ... - ... patris et filii et spiritu sancti. Amen\plain \f0\fs24 , (38\plain \f0\super\fs32 v\plain \f0\fs24 -39\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Oratio ad impetrandum remissionem peccatorum. {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Domine deus, pater omnipotens, qui iustis}}\plain \f0\i\fs24  ... - ... in secula seculorum. Amen. Pater noster. {\field{\*\fldinst HYPERLINK "hida://bezlit[8].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Haimerl, Gebetbuchliteratur, 1952}}\plain \f0\fs24 , S. 91 (539), (40\plain \f0\super\fs32 r\plain \f0\fs24 -41\plain \f0\super\fs32 v\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Dankgebete}}\plain \f0\fs24 , (40\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Incipiunt gratiarum actiones deo omnipotenti per singulos dies hebdoma\plain \f0\fs24 [dae]. Vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 1, S. 254. \plain \f0\i\fs24 Pro dominica die. {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Gratias tibi agimus, omnipotens deus, qui hodie fecisti coeli pulchrytudinem }}\plain \f0\i\fs24 ... - ... da nobis tua\plain \f0\fs24 [m] \plain \f0\i\fs24 claritatem et exclusis tenebris angelorum puritatem per dominum nostrum etc. Amen\plain \f0\fs24 , (40\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 Feria secunda.\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Gratias tibi agimus, omnipotens deus, qui hodie fecisti pulchram sph\u230 \'e6ram}}\plain \f0\i\fs24  ... - ... pascens notabilia tu\u230 \'e6 veritatis et gloria, qui vivis etc. Feria tertia. {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Gratias tibi agimus, omnipotens deus, qui hodie fecisti maria et gramina et herbas}}\plain \f0\i\fs24  ... - ... ut tibi semper placeamini te tamquam discedamus. Per Christum etc. Amen\plain \f0\fs24 , (41\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Feria quarta. {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Gratias tibi agimus, omnipotens deus, qui hodie solem et lunam et stella}}\plain \f0\i\fs24  ... - ... sed te sequendo lucem propre tuam inveniamus. Per Christum. Amen. Feria quinta. {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Gratias tibi agimus, omnipotens deus, qui hodie in aquis pisces, in aeree volatilia creasti}}\plain \f0\i\fs24  ... - ... transeundi ad gaudia paradysi. Per Christum etc. Amen\plain \f0\fs24 , (41\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 Feria sexta. {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Gratias tibi agimus, omnipotens deus, qui hodie fecisti frumenta et reptilia et bestias terr\u230 \'e6}}\plain \f0\i\fs24  ... - ... et te summum bonum eligamus. Per Christum. Amen. Sabbato. {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Gratias tibi agimus, omnipotens deus, qui die septimo ab omni opere, quod patraras, quievisti}}\plain \f0\i\fs24  ... - ... et ad salutem nostram fecisti omnia, qui vivis in secula seculorum. Amen\plain \f0\fs24 , (42\plain \f0\super\fs32 r\plain \f0\fs24 -43\plain \f0\super\fs32 v\plain \f0\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Messgebet}}\plain \f0\scaps\fs24 .\plain \f0\fs24  (42\plain \f0\super\fs32 r\plain \f0\fs24 -43\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 Sequitur devotissima sancti Martini pape ante missam dicendo oratio. {\field{\*\fldinst HYPERLINK "hida://5650[16].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 O domine Iesu Christe, fili dei vivi, miserere mihi misero peccatori}}\plain \f0\i\fs24  ... - ... deus, qui es trinus et vivis per cuncta secula seculorum benedictus. Amen\plain \f0\fs24 , (43\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 Quicumque hanc orationem devote dixerit, tot dies indulgentiarum acquiret, quot fuerunt ... in corpore Iesu tempore passionis eius, qu\u230 \'e6 fuerunt sex milia sexcenta \plain \f0\fs24 [!] \plain \f0\i\fs24 et sexginta \plain \f0\fs24 [!] \plain \f0\i\fs24 (sexta). {\field{\*\fldinst HYPERLINK "hida://5650[17].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Precor te, amantissime domine}}\plain \f0\i\fs24  ... - ... per omnia secula seculorum. Amen. \plain \f0\fs24 Vgl. Leroquais, Les livres d'heures. Manuscrits, Bd. 1, S. XXXI, 336. Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[9].8330/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Haimerl, Gebetbuchliteratur, 1952}}\plain \f0\fs24 , S. 80 (457), 124 (735), }

