\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 Foliierung 1 (zweites Bl. des vorderen Vorsatzes) bis 80 (hinterer Vorsatz) \u183 \'b7\plain \f0\b\fs24  \plain \f0\fs24 19 Zeilen \u183 \'b7\plain \f0\b\fs24  {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Bastarda}}\plain \f0\fs24  einer Hand, {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 franz\u246 \'f6sische Gesch\u228 \'e4ftsschrift}}\plain \f0\fs24  (Nachtrag 75\plain \f0\super\fs32 r\plain \f0\fs24 -78\plain \f0\super\fs32 v\plain \f0\fs24 ) \u183 \'b7\plain \f0\b\fs24  \plain \f0\fs24 Rubrizierung \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Absatz-Lombarden}}\plain \f0\fs24  (\u252 \'fcber 1 Zeile, teilweise in Gold auf rotem oder blauem Grund); Initialen (\u252 \'fcber 2\plain \f0\b\fs24  \plain \f0\fs24 Zeilen, Buchstabenk\u246 \'f6rper rot oder blau, mit Ranken im Camaieu-Stil, Grund in Gold oder in Kontrastfarben mit wei\u223 \'dfen oder goldenen Fadenranken); {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Zeilenf\u252 \'fcllung}}\plain \f0\fs24  (rot oder blau, geometrische Muster, gold); 12\plain \f0\super\fs32 r\plain \f0\fs24  und 38\plain \f0\super\fs32 v\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5270[2]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Teilbord\u252 \'fcre}}\plain \f0\fs24  (mehrfarbige Akanthusranken mit Bl\u252 \'fctenpflanzen und Fr\u252 \'fcchten, goldener Grund, 12\plain \f0\super\fs32 r\plain \f0\fs24  mit Hirsch, Pfau und zwei Putten, die das Wappen st\u252 \'fctzen: oberes Drittel wei\u223 \'df, belegt mit drei roten Drachenk\u246 \'f6pfen, nach links gewendet, mittleres und unteres Drittel rot, belegt mit 2 : 1 goldenen Ringen); 70\plain \f0\super\fs32 v\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5270[3]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initiale}}\plain \f0\fs24  (rot-blau, mit Bord\u252 \'fcrenstab, Keilformen und "Froschlaich"-Besatz); 38\plain \f0\super\fs32 v\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5270[4]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 historisierte Initiale}}\plain \f0\fs24  (Buchstabenk\u246 \'f6rper rosa, mit goldkonturigen Banderolen auf hellblauem Grund mit goldenen Fadenranken, im Binnenfeld K\u246 \'f6nig David); 12\plain \f0\super\fs32 r\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5270[5]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Miniatur}}\plain \f0\fs24  im {\field{\*\fldinst HYPERLINK "hida://5270[6]/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 Architekturrahmen}}\plain \f0\fs24  (Mari\u228 \'e4 Verk\u252 \'fcndigung).}

