\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 15\plain \f0\super\fs32 r\plain \f0\fs24 -22\plain \f0\super\fs32 v\plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Sermones de paenitentia}}\plain \f0\fs24 . \u220 \'dcberschriften rubriziert. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Facite fructus dignos penitencie. Mt. IIII }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 [recte 3,8]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 . In principio quadragesime informandi sunt peccatores}}\plain \f0\i\fs24  ... - ... non perducat sic etiam de penitencia etc.\plain \f0\fs24 , (15\plain \f0\super\fs32 v\plain \f0\fs24 -16\plain \f0\super\fs32 r\plain \f0\fs24 ) \plain \f0\i\fs24 >De penitencia<. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Penitenciam agite, appropinquabit enim regnum celorum. Mt. IIII}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 [,17].}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17  Omne tempus XLe est tempus penitencie}}\plain \f0\i\fs24  ... - ... immensum eterne glorie pondus experatur in nobis etc. Nota, quod ... observant peccatores in sacramento penitencie, quod decet servare in faciendo penitenciam\plain \f0\fs24 , (16\plain \f0\super\fs32 rv\plain \f0\fs24 ) \plain \f0\i\fs24 >De penitencia<. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Primum est velocitas sive festinatio}}\plain \f0\i\fs24  ... - ... usque ad mortem, quod nobis etc.\plain \f0\fs24 , (16\plain \f0\super\fs32 v\plain \f0\fs24 -18\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 >De VIII generibus hominum penitencium<. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Octo sunt genera hominum penitencium, quorum VII deo displicent, octavum deo et istorum penitencia laudabile et fructuosa}}\plain \f0\i\fs24  ... - ... quod tibi in morte tua\plain \f0\fs24 , (18\plain \f0\super\fs32 v\plain \f0\fs24 -19\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 >De penitencia<. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Penitenciam agite in remissionem peccatorum, ut dicitur}}\plain \f0\i\fs24  ... - ... sed mortificata resurgant\plain \f0\fs24 , (19\plain \f0\super\fs32 v\plain \f0\fs24 ) Glosse, (19\plain \f0\super\fs32 v\plain \f0\fs24 -20\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 >De conversione sermo<. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Si confiteamur peccata nostra, fidelis et iustus est deo}}\plain \f0\i\fs24  ... - ... virtus eorum non morietur etc.\plain \f0\fs24 , (20\plain \f0\super\fs32 v\plain \f0\fs24 -22\plain \f0\super\fs32 v\plain \f0\fs24 ) \plain \f0\i\fs24 >De confessione<. {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 Qui abscondit scelera sua, non dirigetur }}{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f0\fs24\chcbpat17 [Prv 28,13]}}{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f0\i\fs24\chcbpat17 . Qui autem confessus fuerit, ea et reliquit, misericordiam consequitur}}\plain \f0\i\fs24  ... - ... si nollet omnia vulnera sua  sanari etc.}

