\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24 110\plain \f0\super\fs32 r\plain \f0\fs24 -114\plain \f0\super\fs32 r\plain \f0\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 Ps.-Augustinus}}\plain \f0\scaps\fs24 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f0\scaps\fs24\chcbpat17 De duodecim abusivis saeculi}}\plain \f0\scaps\fs24 . \plain \f0\i\fs24 Incipit tractatus beati Cypriani \plain \f0\fs24 [!] \plain \f0\i\fs24 episcopi et martyris de XII abusionibus. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Primus abusionis gradus, si sine operibus bonis sapiens et }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 [non] }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 predicator fuerit, qui, quod sermone docet, actibus complere negligit}}\plain \f1\i\lang1033\fs24\cf1  ... - ... non sumus itaque sine Christo in hoc transitorio tempore ne sine nobis Christus esse incipiat in futuro. Amen\plain \f1\lang1033\fs24\cf1 , (114\plain \f1\super\lang1033\fs32\cf1 r\plain \f1\lang1033\fs24\cf1 ) Inhaltsverzeichnis. \plain \f1\i\lang1033\fs24\cf1 Sequitur capitula XII abusionum. Sapiens sine operibus ... - ... Populus sine lege. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 CPL}}\plain \f1\lang1033\fs24\cf1  1106. Inkunabeln und Drucke: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 GW}}\plain \f1\lang1033\fs24\cf1  2933-GW 2935. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 MPL}}\plain \f1\lang1033\fs24\cf1  4, Sp. 947B-960D; {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 MPL}}\plain \f1\lang1033\fs24\cf1  40, Sp. 1079B-1088C; {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 CSEL}}\plain \f1\lang1033\fs24\cf1  3/3, S. 152-173.}

