\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs24 311, 344, 441, 437 und 459 nach der Bindung entfernt (gleicher Befund wie 1901), 435 und 436 weisen Schnittspuren auf (entstanden beim Entfernen von 437), ein St\u252 \'fcck von 394 am unteren Rand ausgeschnitten (Besitzvermerk?), auf einigen Bll. mit Buchschmuck teilweise Verlust der Farbschicht, vordere Bll. berieben und durch Wurm besch\u228 \'e4digt \u183 \'b7 moderne Foliierung I (vorderer Vorsatz, Papier), Altfoliierung 1-489, moderne Foliierung 490-491 (hinterer Vorsatz, Papier) \u183 \'b7\plain \f1\b\fs24  \plain \f1\fs24 53 Zeilen;\plain \f1\b\fs24  \plain \f1\fs24 2 Spalten \u183 \'b7\plain \f1\b\fs24  {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Rotunda}}\plain \f1\fs24  einer Hand; Corrigenda und Addenda des Schreibers in rot-blauen Rahmen und Marginalien einer Hand des 15./16. Jhs. \u183 \'b7\plain \f1\b\fs24  \plain \f1\fs24 Rubrizierung \u183 \'b7 Bord\u252 \'fcrenst\u228 \'e4be (Fleuronn\u233 \'e9e-Elemente, florale Friese, Ketten und andere Motive); {\field{\*\fldinst HYPERLINK "hida://5270[2]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Lombarden}}\plain \f1\fs24  (rot oder blau, als Versalien in den Rahmen integriert); {\field{\*\fldinst HYPERLINK "hida://5270[4]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Tierinitialen}}\plain \f1\fs24  (Emailtyp); {\field{\*\fldinst HYPERLINK "hida://5270[3]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 historisierte Initialen}}\plain \f1\fs24  ({\field{\*\fldinst HYPERLINK "hida://5270[5]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Randleisteninitialen}}\plain \f1\fs24 , Emailtyp, groteskenartige Abschl\u252 \'fcsse der Bord\u252 \'fcrenst\u228 \'e4be, Szenen des Alten und Neuen Testaments sowie Dominikanerm\u246 \'f6nche); 1\plain \f1\super\fs32 r\plain \f1\fs24 , 3\plain \f1\super\fs32 v {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Bord\u252 \'fcre}}\plain \f1\fs24  ({\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f1\fs24\chcbpat17 Medaillons}}\plain \f1\fs24  mit Heiligenfiguren, Kreuzigungssene mit Muttergottes, Johannes und Dominikanern, Bibelszenen und Lamm Gottes, Groteskenelemente, Flechtbandknoten, goldener Grund); 376\plain \f1\super\fs32 r\plain \f1\fs24  Initiale \plain \f1\i\fs24 L \plain \f1\fs24 zur Spaltentrennung (Wurzel Jesse, Medaillons mit Halbfiguren der Vorfahren Jesu, am Kopfende Medaillon mit Halbfigur des Erl\u246 \'f6sers, goldener Grund).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

